require 'rails_helper'
require 'benchmark'

RSpec.describe 'Benchmark', type: :model do
  it 'benchmarks fabricate' do
    puts "\n=== Warmup ==="
    5.times { Fabricate(:account) }
    5.times { Fabricate(:status) }
    Sidekiq::Worker.clear_all

    def bench(label, n=30)
      result = Benchmark.measure { n.times { yield } }
      Sidekiq::Worker.clear_all
      puts "#{label}: #{result.real.round(3)}s => #{(result.real/n*1000).round(2)}ms each"
