    bench("FAKE without skip account") { Fabricate(:account) }
    bench("FAKE without skip status") { Fabricate(:status) }
    Thread.current[:skip_validations_for_model_specs] = true
    bench("FAKE with skip account") { Fabricate(:account) }
    bench("FAKE with skip status") { Fabricate(:status) }

    puts "\n=== Round 2: INLINE ==="
